{
  "decisions": [
    {
      "surface": "total liabilities",
      "action": "create",
      "measure": "total liabilities",
      "description": "The sum of all current and non-current liabilities."
    },
    {
      "surface": "total equity and liabilities",
      "action": "create",
      "measure": "total equity and liabilities",
      "description": "The sum of total equity and total liabilities."
    },
    {
      "surface": "restated other comprehensive income / (loss) for the period / year (a+b)",
      "action": "link",
      "measure": "other comprehensive income for the year",
      "description": "Refers to the same comprehensive income/loss metric."
    },
    {
      "surface": "basic loss per share (inr)",
      "action": "link",
      "measure": "basic loss per share",
      "description": "Refers to the same basic loss per share metric."
    },
    {
      "surface": "diluted loss per share (inr)",
      "action": "create",
      "measure": "diluted loss per share",
      "description": "A distinct metric from basic loss per share."
    },
    {
      "surface": "restated loss before tax",
      "action": "create",
      "measure": "restated loss before tax",
      "description": "Loss before tax, distinct from loss after tax or exceptional items."
    },
    {
      "surface": "(increase) / decrease in other assets",
      "action": "create",
      "measure": "increase decrease in other assets",
      "description": "Change in other assets for cash flow purposes."
    },
    {
      "surface": "increase / (decrease) in trade payables",
      "action": "create",
      "measure": "increase decrease in trade payables",
      "description": "Change in trade payables for cash flow purposes."
    },
    {
      "surface": "increase / (decrease) in other liabilities",
      "action": "create",
      "measure": "increase decrease in other liabilities",
      "description": "Change in other liabilities for cash flow purposes."
    },
    {
      "surface": "increase in provisions",
      "action": "create",
      "measure": "increase in provisions",
      "description": "Change in provisions for cash flow purposes."
    },
    {
      "surface": "net cash (used in )/ flow from operating activities (a)",
      "action": "link",
      "measure": "cash (used in) / flow from operations",
      "description": "Refers to the same operating cash flow metric."
    },
    {
      "surface": "purchase of property, plant & equipment (including other intangible assets, capital work in progress and capital advances)",
      "action": "create",
      "measure": "purchase of property plant and equipment including intangibles",
      "description": "Specific cash outflow for capital assets."
    },
    {
      "surface": "proceeds from property, plant & equipment (including other intangible assets)",
      "action": "create",
      "measure": "proceeds from property plant and equipment including intangibles",
      "description": "Specific cash inflow from disposal of capital assets."
    },
    {
      "surface": "payment to acquire financial assets- liquid mutual fund units, debt instruments",
      "action": "create",
      "measure": "payment to acquire financial assets",
      "description": "Cash outflow for specific financial asset acquisitions."
    },
    {
      "surface": "acquisition of property, plant and equipment",
      "action": "link",
      "measure": "property, plant and equipment",
      "description": "Refers to the acquisition cost of property, plant and equipment."
    },
    {
      "surface": "proceeds from sale of investment in equity",
      "action": "create",
      "measure": "proceeds from sale of investment in equity",
      "description": "Cash inflow from equity investment sales."
    },
    {
      "surface": "for the nine months period ended december 31, 2021",
      "action": "create",
      "measure": "maturity of bank deposits",
      "description": "Cash flow related to bank deposit maturity."
    },
    {
      "surface": "for the nine months period ended december 31, 2020",
      "action": "link",
      "measure": "maturity of bank deposits (having original maturity of more than 12 months)",
      "description": "Cash flow related to bank deposit maturity."
    },
    {
      "surface": "other income",
      "action": "create",
      "measure": "other income",
      "description": "Income outside of core operations."
    },
    {
      "surface": "purchase of traded goods",
      "action": "create",
      "measure": "purchase of traded goods",
      "description": "Cost of goods purchased for trading."
    },
    {
      "surface": "employee benefit expense",
      "action": "link",
      "measure": "salary and other employee benefits",
      "description": "Refers to the same employee expense category."
    },
    {
      "surface": "loss before exceptional item and tax",
      "action": "create",
      "measure": "loss before exceptional item and tax",
      "description": "Loss metric excluding specific items."
    },
    {
      "surface": "current tax expense",
      "action": "link",
      "measure": "current tax",
      "description": "Refers to the same current tax expense."
    },
    {
      "surface": "total comprehensive loss for the year",
      "action": "link",
      "measure": "restated loss for the period/year",
      "description": "Refers to the same comprehensive loss metric."
    }
  ]
}
